  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 1, 'Identificar a base de uma porcentagem', 'Uma porcentagem sempre se refere a uma base: o todo, o preço inicial ou o grupo definido pela pergunta. Em mudanças sucessivas, o resultado de uma etapa pode virar a base da seguinte. Percentual e ponto percentual não são a mesma medida.', '## 1. Pergunte “por cento de quê?”
A expressão 25% significa 25 em cada 100 da base indicada. Antes de calcular, encontre o todo ou grupo de referência. Em “25% dos 40 estudantes”, a base é 40 estudantes. Em “20% entre as pessoas inscritas”, a base é o grupo de inscritos.

## 2. Separe quatro valores
A **base** é a referência; a **taxa** é o percentual; a **parte** é o resultado da aplicação; a **diferença** mede quanto um valor mudou em unidades. Eles podem ter números próximos, mas são papéis diferentes. Se 15% de 200 livros são destinados a um projeto, 200 é a base, 15% é a taxa e 30 livros é a parte.

## 3. Variação percentual usa o valor inicial
Ao comparar um valor que passa de 80 para 100, a diferença é 20. Para calcular o aumento relativo “em relação ao valor inicial”, a base é 80. O valor final não substitui a referência inicial. Sempre leia a direção: “de ___ para ___”.

## 4. Grupos condicionais mudam a base
“Entre os participantes”, “dos inscritos” ou “dentro do grupo que respondeu” define o denominador. Se 12 de 18 participantes frequentam semanalmente, a base dessa taxa é 18, ainda que a escola tenha 200 estudantes. Uma pergunta diferente pode usar a escola inteira como referência.

## 5. Atualize a base em etapas sucessivas
Um item de R$ 100 aumenta 20%: a parte é R$ 20 e o novo preço é R$ 120. Um desconto posterior calculado sobre o preço atualizado usa R$ 120 como base, não os R$ 100 iniciais. Repetir a mesma taxa não significa repetir a mesma base.

## 6. Distinga porcentagem e ponto percentual
Uma taxa que passa de 20% para 25% aumenta 5 pontos percentuais. A variação relativa é calculada em relação aos 20% iniciais e não é igual a 5%. Ao ler “cresceu 5%”, pergunte qual valor foi usado como base e qual unidade de mudança está sendo apresentada.

## Exemplo resolvido
Uma tarifa passa de R$ 50 para R$ 54. A diferença absoluta é R$ 4. Para uma variação percentual desde o preço anterior, a base é R$ 50: a taxa é 4 ÷ 50 = 0,08 = 8%. Se depois houver desconto, o novo preço de R$ 54 será a base da próxima operação.

## 7. Verifique se a conclusão responde à pergunta
Um percentual maior não garante uma quantidade maior quando os grupos têm tamanhos diferentes. Identifique a base de cada taxa e, se a pergunta pedir quantidade, calcule cada parte usando sua própria base.',
    'Uma tarifa de R$ 80 aumenta 10% e depois recebe desconto de 10% sobre o valor atualizado. Primeiro: a base é R$ 80; 10% corresponde a R$ 8, então o novo valor é R$ 88. Segundo: a base agora é R$ 88; 10% corresponde a R$ 8,80. O resultado final é R$ 79,20. As taxas são iguais, mas as bases não.', array['Circule o grupo que vem depois de “de”, “dos” ou “entre”.', 'Escreva base, taxa, parte e diferença em campos separados.', 'Em “de A para B”, use A como base da variação relativa.', 'Atualize o valor antes de uma segunda operação.', 'Escreva “pontos percentuais” quando comparar diferença direta entre taxas.']::text[], 30, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-math-percent-base-reference","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Reconhecer parte e todo em uma situação.","Calcular fração decimal simples e multiplicar um valor por 0,1 ou 0,25."],"key_concepts":["base percentual","parte","taxa","denominador","valor inicial","variação percentual","porcentagem sucessiva","ponto percentual"],"progression":[{"stage":"DIAGNOSTIC","focus":"Identificar o todo, a taxa e o valor inicial em frases curtas.","questionIds":["v5-math-percent-base-01","v5-math-percent-base-02","v5-math-percent-base-03","v5-math-percent-base-04"]},{"stage":"PRACTICE","focus":"Escolher a base em preços, grupos condicionais e mudanças simples.","questionIds":["v5-math-percent-base-05","v5-math-percent-base-06","v5-math-percent-base-07","v5-math-percent-base-08","v5-math-percent-base-09","v5-math-percent-base-10","v5-math-percent-base-11","v5-math-percent-base-12","v5-math-percent-base-13","v5-math-percent-base-14","v5-math-percent-base-15","v5-math-percent-base-16","v5-math-percent-base-17","v5-math-percent-base-18"]},{"stage":"TRANSFER","focus":"Analisar subgrupos, etapas sucessivas e comparação entre taxas e quantidades.","questionIds":["v5-math-percent-base-19","v5-math-percent-base-20","v5-math-percent-base-21","v5-math-percent-base-22","v5-math-percent-base-23","v5-math-percent-base-24","v5-math-percent-base-25","v5-math-percent-base-26"]},{"stage":"CONSOLIDATION","focus":"Corrigir confusões entre valor inicial, final, parte e pontos percentuais.","questionIds":["v5-math-percent-base-27","v5-math-percent-base-28","v5-math-percent-base-29","v5-math-percent-base-30","v5-math-percent-base-31"]},{"stage":"REVIEW","focus":"Retomar bases condicionais e atualizar referências em novas situações.","questionIds":["v5-math-percent-base-32","v5-math-percent-base-33","v5-math-percent-base-34","v5-math-percent-base-35","v5-math-percent-base-36","v5-math-percent-base-37","v5-math-percent-base-38","v5-math-percent-base-39","v5-math-percent-base-40"]}],"micro_explanations":[{"trigger":"FIND_THE_WHOLE","text":"A base responde “qual total ou grupo está sendo considerado?”."},{"trigger":"PART_RATE_BASE","text":"A taxa é o percentual; a base é a referência; a parte é o resultado do cálculo."},{"trigger":"INITIAL_VALUE","text":"A variação relativa “de A para B” usa A como base."},{"trigger":"CONDITIONAL_GROUP","text":"“Entre os participantes” restringe a base ao grupo participante."},{"trigger":"UPDATE_BASE","text":"Depois de uma mudança, use o valor atualizado como base da próxima etapa quando o enunciado disser isso."},{"trigger":"POINTS_VS_PERCENT","text":"Diferença direta entre duas taxas é medida em pontos percentuais; variação relativa tem uma base."}],"remediations":[{"id":"LABEL_FOUR_VALUES","misconception":"Confundir base, taxa, parte e diferença.","prompt":"Crie quatro campos e atribua a cada número seu papel. Se algum campo não foi informado, não o invente."},{"id":"MARK_INITIAL_VALUE","misconception":"Usar o valor final como base de crescimento.","prompt":"Reescreva a mudança como “de ___ para ___”. Circule o primeiro valor e use-o como base da variação relativa."},{"id":"SELECT_CONDITIONED_GROUP","misconception":"Usar o total geral quando a pergunta especifica um subgrupo.","prompt":"Sublinhe a expressão “entre ___”. Esse grupo define o denominador; compare a parte com ele."},{"id":"UPDATE_SUCCESSIVE_BASE","misconception":"Aplicar taxas sucessivas sempre ao valor original.","prompt":"Calcule o valor após a primeira etapa. Copie-o para a linha da próxima base antes de aplicar a nova taxa."},{"id":"DISTINGUISH_POINTS","misconception":"Chamar diferença em pontos percentuais de aumento percentual.","prompt":"Subtraia as taxas para obter pontos percentuais. Depois, se pedirem variação relativa, divida essa diferença pela taxa inicial."},{"id":"COMPARE_RATE_AND_COUNT","misconception":"Tratar maior percentual como maior quantidade.","prompt":"Multiplique cada taxa pela base do próprio grupo. Compare depois as quantidades e as taxas separadamente."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"publisher":"TecEscola","title":"Conjunto didático sintético de bases percentuais","license":"Situações, dados e itens autorais; não utilizam dados pessoais nem reivindicam mapeamento oficial."}],"copyright_note":"Questões, dados, explicações e atividade são autorais e sintéticos. Revisão pedagógica pendente; alinhamento oficial não reivindicado.","authentic_activities":[{"id":"v5-math-percent-base-denominator-audit","title":"Auditoria de bases em indicadores","objective":"Identificar denominadores e bases em indicadores fictícios e explicar como a escolha altera a interpretação.","context":"Atividade em sala com conjunto de dados sintético criado pelo docente; não usar dados pessoais, saúde, renda ou desempenho identificável de estudantes.","materials":["Tabela fictícia com grupos e taxas","Planilha ou calculadora","Quadro para base, taxa, parte e interpretação"],"instructions":"Para cada indicador, anote a população de referência e o subgrupo observado. Recalcule uma parte e compare dois grupos com bases distintas. Identifique uma frase que confunda taxa e contagem e reescreva-a com a base explícita.","evidence":"Tabela preenchida com denominadores corretos, cálculo verificável e explicação que distingue percentual de quantidade absoluta.","safety":"Usar exclusivamente dados sintéticos; não classificar nem comparar estudantes reais. Disponibilizar calculadora e formatos acessíveis.","privacyGuard":"Não inserir nomes, notas, frequência, renda, saúde ou outros dados pessoais. As respostas avaliam a modelagem matemática, não características de grupos reais.","ageRange":"Ensino Fundamental II, com números e contextos ajustados à turma.","mediation":"O docente verifica o denominador antes do cálculo e pede que a turma explicite quando uma taxa usa subgrupo ou total geral.","rubric":[{"criterion":"Identificação da base","emerging":"Usa a parte ou a taxa como denominador.","developing":"Encontra o total com apoio, mas perde o subgrupo.","proficient":"Nomeia corretamente a referência e o grupo ao qual a taxa se aplica."},{"criterion":"Cálculo e mudança","emerging":"Aplica percentual ao valor final ou repete base em etapas.","developing":"Atualiza a base após orientação.","proficient":"Calcula cada etapa com a base correspondente e registra unidades."},{"criterion":"Interpretação","emerging":"Confunde taxa com quantidade absoluta.","developing":"Compara taxas ou quantidades parcialmente.","proficient":"Distingue percentual, contagem e ponto percentual e explica limites."}]}],"source_question_feedback":[{"questionId":"v4-authored-mathematics-percent-base-probe-01","hint":"A base é o valor de referência para aquela taxa. Marque o todo ou o grupo indicado; em uma sequência, atualize a base depois de cada mudança.","errorFocus":"PERCENTAGE_BASE_PART_AND_RATE_DISTINCTION"},{"questionId":"v4-authored-mathematics-percent-base-probe-02","hint":"A base é o valor de referência para aquela taxa. Marque o todo ou o grupo indicado; em uma sequência, atualize a base depois de cada mudança.","errorFocus":"PERCENTAGE_BASE_PART_AND_RATE_DISTINCTION"},{"questionId":"v4-authored-mathematics-percent-base-practice-01","hint":"A base é o valor de referência para aquela taxa. Marque o todo ou o grupo indicado; em uma sequência, atualize a base depois de cada mudança.","errorFocus":"PERCENTAGE_BASE_PART_AND_RATE_DISTINCTION"},{"questionId":"v4-authored-mathematics-percent-base-practice-02","hint":"A base é o valor de referência para aquela taxa. Marque o todo ou o grupo indicado; em uma sequência, atualize a base depois de cada mudança.","errorFocus":"PERCENTAGE_BASE_PART_AND_RATE_DISTINCTION"},{"questionId":"v4-authored-mathematics-percent-base-transfer-01","hint":"A base é o valor de referência para aquela taxa. Marque o todo ou o grupo indicado; em uma sequência, atualize a base depois de cada mudança.","errorFocus":"PERCENTAGE_BASE_PART_AND_RATE_DISTINCTION"},{"questionId":"v4-authored-mathematics-percent-base-lock-in-01","hint":"A base é o valor de referência para aquela taxa. Marque o todo ou o grupo indicado; em uma sequência, atualize a base depois de cada mudança.","errorFocus":"PERCENTAGE_BASE_PART_AND_RATE_DISTINCTION"},{"questionId":"v4-authored-mathematics-percent-base-review-01","hint":"A base é o valor de referência para aquela taxa. Marque o todo ou o grupo indicado; em uma sequência, atualize a base depois de cada mudança.","errorFocus":"PERCENTAGE_BASE_PART_AND_RATE_DISTINCTION"},{"questionId":"v4-authored-mathematics-percent-base-review-02","hint":"A base é o valor de referência para aquela taxa. Marque o todo ou o grupo indicado; em uma sequência, atualize a base depois de cada mudança.","errorFocus":"PERCENTAGE_BASE_PART_AND_RATE_DISTINCTION"}],"objective":"Determinar o valor ou grupo de referência de uma taxa percentual e distinguir base, parte, taxa e variação em situações de uma ou mais etapas.","common_mistake":"Usar a parte, a taxa, o valor final ou a diferença como denominador sem verificar a pergunta; manter a base original em mudanças sucessivas; ou comparar percentuais como se fossem contagens.","estimated_minutes":30}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
