  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-math-percent-base-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"LIBRARY_BOOKS","statement":"Uma biblioteca recebeu 120 livros e separou 10% para uma estante infantil. Antes de calcular a quantidade separada, qual é a base?","options":["120 livros, o total recebido.","10 livros, uma quantidade ainda não calculada.","10%, a taxa aplicada.","A quantidade que ficará na estante infantil, que não foi informada."],"correctAnswer":"120 livros, o total recebido.","explanation":"A base é o total sobre o qual incide a taxa. Aqui, 10% incide sobre os 120 livros recebidos.","hint":"Localize o todo descrito antes da expressão “10%”.","errorFocus":"PERCENT_RATE_CONFUSED_WITH_BASE","misconceptions":{"10 livros, uma quantidade ainda não calculada.":["PERCENT_RATE_CONFUSED_WITH_BASE"]},"position":1},{"id":"v5-math-percent-base-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"CLASS_SURVEY","statement":"Em uma turma de 40 estudantes, 25% responderam a uma enquete. Qual número é a base da porcentagem?","options":["25 estudantes, resultado que não foi informado.","40 estudantes, o total da turma.","25%, a taxa de resposta.","O número de respostas, que não foi informado."],"correctAnswer":"40 estudantes, o total da turma.","explanation":"A porcentagem compara a parte com um todo de referência: neste caso, os 40 estudantes da turma.","hint":"Pergunte “25% de qual total?”.","errorFocus":"PART_CONFUSED_WITH_BASE","misconceptions":{"25 estudantes, resultado que não foi informado.":["PART_CONFUSED_WITH_BASE"]},"position":2},{"id":"v5-math-percent-base-03","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"WATER_TANK","statement":"Um reservatório com 500 litros estava cheio e perdeu 5% do volume. Sobre qual quantidade se calcula a perda?","options":["5 litros, uma perda que não foi calculada.","5%, a taxa de perda.","500 litros, o volume inicial informado.","O volume que restou, ainda desconhecido."],"correctAnswer":"500 litros, o volume inicial informado.","explanation":"Como a perda é calculada a partir do volume antes da retirada, a base inicial é 500 litros.","hint":"Diferencie o volume antes e depois da perda.","errorFocus":"FINAL_VALUE_USED_AS_INITIAL_BASE","misconceptions":{"5 litros, uma perda que não foi calculada.":["FINAL_VALUE_USED_AS_INITIAL_BASE"]},"position":3},{"id":"v5-math-percent-base-04","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"TICKET_PRICE","statement":"Um ingresso custava R$ 80 e recebeu desconto de 15%. Qual valor é a base do desconto?","options":["R$ 15, valor do desconto sem cálculo.","15%, a taxa anunciada.","O preço final, que ainda não foi calculado.","R$ 80, preço antes do desconto."],"correctAnswer":"R$ 80, preço antes do desconto.","explanation":"A taxa de desconto incide no preço original de R$ 80.","hint":"Procure o preço “antes” da mudança.","errorFocus":"DISCOUNT_RATE_CONFUSED_WITH_AMOUNT","misconceptions":{"R$ 15, valor do desconto sem cálculo.":["DISCOUNT_RATE_CONFUSED_WITH_AMOUNT"]},"position":4},{"id":"v5-math-percent-base-05","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"SCHOOL_MATERIALS","statement":"Uma escola tinha 200 cadernos e destinou 30% a um projeto. Qual quantidade funciona como base?","options":["200 cadernos, o total disponível antes da destinação.","30 cadernos, uma parte ainda não calculada.","30%, a taxa de destinação.","A quantidade que sobrou, que não foi informada."],"correctAnswer":"200 cadernos, o total disponível antes da destinação.","explanation":"O percentual de destinação é aplicado ao total inicial de 200 cadernos.","hint":"A base é o todo que dá origem à parte percentual.","errorFocus":"REMAINING_PART_USED_AS_BASE","misconceptions":{"30 cadernos, uma parte ainda não calculada.":["REMAINING_PART_USED_AS_BASE"]},"position":1},{"id":"v5-math-percent-base-06","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"BUS_PASS","statement":"Uma passagem de R$ 6,00 teve aumento de 5%. Qual valor é a base do aumento?","options":["R$ 5,00, a taxa lida sem unidade de preço.","R$ 6,00, o preço antes do aumento.","5%, o percentual de aumento.","O preço posterior, ainda não informado."],"correctAnswer":"R$ 6,00, o preço antes do aumento.","explanation":"O aumento percentual é calculado sobre o preço anterior de R$ 6,00.","hint":"Identifique o preço no início da situação.","errorFocus":"PERCENT_CHANGE_BASE_OMITTED","misconceptions":{"R$ 5,00, a taxa lida sem unidade de preço.":["PERCENT_CHANGE_BASE_OMITTED"]},"position":2},{"id":"v5-math-percent-base-07","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"ATTENDANCE","statement":"De 60 estudantes inscritos em uma atividade, 45 compareceram. Para expressar a presença como porcentagem dos inscritos, qual é a base?","options":["45 estudantes presentes.","15 estudantes ausentes.","60 estudantes inscritos.","A porcentagem de presença, ainda não calculada."],"correctAnswer":"60 estudantes inscritos.","explanation":"A pergunta compara presentes com inscritos; portanto, o total de inscritos é a referência.","hint":"A base depende do grupo usado no denominador da comparação.","errorFocus":"NUMERATOR_CONFUSED_WITH_DENOMINATOR","misconceptions":{"45 estudantes presentes.":["NUMERATOR_CONFUSED_WITH_DENOMINATOR"]},"position":3},{"id":"v5-math-percent-base-08","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"STORE_PRICE","statement":"Um produto custa R$ 150. O desconto é de 20% e depois o preço com desconto é comparado com outro produto. Qual é a base para calcular o desconto inicial?","options":["R$ 120, preço após o desconto, que ainda não foi calculado.","20%, taxa do desconto.","O preço do outro produto, sem relação com este desconto.","R$ 150, o preço antes do desconto."],"correctAnswer":"R$ 150, o preço antes do desconto.","explanation":"O desconto inicial usa o preço original como base. Uma comparação posterior pode usar outros valores, mas não altera essa etapa.","hint":"Marque cada etapa antes de escolher a base.","errorFocus":"LATER_COMPARISON_VALUE_USED_FOR_FIRST_CHANGE","misconceptions":{"R$ 120, preço após o desconto, que ainda não foi calculado.":["LATER_COMPARISON_VALUE_USED_FOR_FIRST_CHANGE"]},"position":4},{"id":"v5-math-percent-base-09","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"IDENTIFY","contextFamily":"LIBRARY_LOANS","statement":"Uma biblioteca registrou 90 empréstimos em abril e 108 em maio. Para calcular o aumento percentual de abril para maio, qual valor é a base?","options":["90 empréstimos, o valor inicial de abril.","108 empréstimos, o valor final de maio.","18 empréstimos, a diferença entre os meses.","A média dos dois meses, que não é a referência indicada."],"correctAnswer":"90 empréstimos, o valor inicial de abril.","explanation":"O aumento percentual de abril para maio é relativo ao valor inicial de abril. A diferença é 18, mas não é a base.","hint":"Separe valor inicial, valor final e variação.","errorFocus":"CHANGE_AMOUNT_USED_AS_BASE","misconceptions":{"108 empréstimos, o valor final de maio.":["CHANGE_AMOUNT_USED_AS_BASE"]},"position":5},{"id":"v5-math-percent-base-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"TWO_CLASSES","statement":"A turma A tem 20 estudantes e 5 faltas; a turma B tem 40 estudantes e 8 faltas. Para comparar a taxa de faltas, qual informação serve de base em cada turma?","options":["As faltas: 5 na A e 8 na B, sem considerar o tamanho das turmas.","O total de estudantes de cada turma: 20 na A e 40 na B.","A diferença de 3 faltas entre as turmas.","O total combinado de 60 para calcular ambas as taxas separadamente."],"correctAnswer":"O total de estudantes de cada turma: 20 na A e 40 na B.","explanation":"Cada taxa é uma parte em relação ao total de sua própria turma. A mesma quantidade de faltas não teria o mesmo percentual em grupos de tamanhos diferentes.","hint":"Associe cada numerador ao seu próprio grupo total.","errorFocus":"COMMON_DENOMINATOR_ASSUMED_FOR_DISTINCT_GROUPS","misconceptions":{"As faltas: 5 na A e 8 na B, sem considerar o tamanho das turmas.":["COMMON_DENOMINATOR_ASSUMED_FOR_DISTINCT_GROUPS"]},"position":6},{"id":"v5-math-percent-base-11","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"IDENTIFY","contextFamily":"ENERGY_BILL","statement":"Uma conta de energia passou de R$ 240 para R$ 276. Qual é a base para calcular o aumento percentual?","options":["R$ 276, o valor depois do aumento.","R$ 36, a diferença entre os valores.","R$ 240, o valor antes do aumento.","R$ 258, a média, que não foi definida como referência."],"correctAnswer":"R$ 240, o valor antes do aumento.","explanation":"A variação percentual usa o valor inicial como referência: R$ 240. A diferença é o aumento absoluto.","hint":"O enunciado pergunta o aumento “de” um valor inicial “para” outro.","errorFocus":"FINAL_VALUE_OR_DIFFERENCE_USED_AS_BASE","misconceptions":{"R$ 276, o valor depois do aumento.":["FINAL_VALUE_OR_DIFFERENCE_USED_AS_BASE"]},"position":7},{"id":"v5-math-percent-base-12","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"IDENTIFY","contextFamily":"SURVEY_SUBGROUP","statement":"Em uma pesquisa com 100 pessoas, 40 usam bicicleta; entre essas 40, 10 usam bicicleta para ir à escola. Para a porcentagem que vai à escola entre quem usa bicicleta, qual é a base?","options":["100 pessoas pesquisadas.","10 pessoas, a parte observada.","60 pessoas que não usam bicicleta.","40 pessoas que usam bicicleta."],"correctAnswer":"40 pessoas que usam bicicleta.","explanation":"A expressão “entre quem usa bicicleta” define o grupo de referência: 40 pessoas.","hint":"Leia o grupo indicado depois de “entre”.","errorFocus":"OVERALL_SAMPLE_USED_INSTEAD_OF_SUBGROUP","misconceptions":{"100 pessoas pesquisadas.":["OVERALL_SAMPLE_USED_INSTEAD_OF_SUBGROUP"]},"position":8},{"id":"v5-math-percent-base-13","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"IDENTIFY","contextFamily":"PRICE_AFTER_TAX","statement":"Um item custa R$ 100 antes de um imposto de 12%; depois do imposto, o preço é usado para calcular um desconto de 10%. Qual é a base do segundo percentual?","options":["O preço após o imposto, R$ 112.","R$ 100, base do primeiro percentual.","12%, a taxa do imposto.","10%, a taxa do desconto."],"correctAnswer":"O preço após o imposto, R$ 112.","explanation":"Em uma sequência, o segundo percentual incide sobre o valor já atualizado. Primeiro, R$ 100 aumenta 12% para R$ 112; esse valor é a base da redução seguinte.","hint":"Cada etapa pode criar uma nova base.","errorFocus":"ORIGINAL_BASE_REUSED_AFTER_INTERMEDIATE_CHANGE","misconceptions":{"R$ 100, base do primeiro percentual.":["ORIGINAL_BASE_REUSED_AFTER_INTERMEDIATE_CHANGE"]},"position":9},{"id":"v5-math-percent-base-14","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"PERCENTAGE_POINTS","statement":"A taxa de participação passou de 20% para 25%. Para calcular o aumento percentual relativo da taxa, qual valor é a base?","options":["25%, a taxa final.","20%, a taxa inicial.","5 pontos percentuais, a diferença absoluta.","100%, o total de referência da taxa original."],"correctAnswer":"20%, a taxa inicial.","explanation":"A comparação da mudança relativa entre taxas usa a taxa inicial de 20% como base. A diferença de 5 pontos percentuais é outra medida.","hint":"Diferencie a diferença em pontos percentuais da variação relativa.","errorFocus":"PERCENTAGE_POINTS_CONFUSED_WITH_PERCENT_CHANGE","misconceptions":{"25%, a taxa final.":["PERCENTAGE_POINTS_CONFUSED_WITH_PERCENT_CHANGE"]},"position":10},{"id":"v5-math-percent-base-15","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"IDENTIFY","contextFamily":"PART_OF_BUDGET","statement":"Um orçamento de R$ 2.000 destina 15% à manutenção. Qual valor é a base do percentual, antes de calcular a parcela?","options":["R$ 300, parcela calculada.","15%, a taxa destinada.","R$ 2.000, o orçamento total.","R$ 1.700, o restante após a destinação."],"correctAnswer":"R$ 2.000, o orçamento total.","explanation":"O todo inicial é R$ 2.000. O valor de R$ 300 é a parte correspondente, não a base.","hint":"Antes de multiplicar taxa e valor, nomeie o todo.","errorFocus":"CALCULATED_PART_CONFUSED_WITH_WHOLE","misconceptions":{"R$ 300, parcela calculada.":["CALCULATED_PART_CONFUSED_WITH_WHOLE"]},"position":11},{"id":"v5-math-percent-base-16","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"MIXED_GROUP_RATES","statement":"Uma escola relata 30% de participação no clube; outra, 45%. Antes de afirmar qual teve mais participantes em quantidade, o que é necessário?","options":["Comparar somente 45% com 30% e concluir a quantidade absoluta.","Somar os dois percentuais.","Usar o número de participantes da escola menor como base para ambas.","Conhecer a base de cada percentual, isto é, o total de estudantes considerado em cada escola."],"correctAnswer":"Conhecer a base de cada percentual, isto é, o total de estudantes considerado em cada escola.","explanation":"Percentuais maiores não garantem maior quantidade absoluta se os totais de referência forem diferentes.","hint":"Um percentual só se torna quantidade quando combinado com sua base.","errorFocus":"RATE_COMPARED_AS_ABSOLUTE_COUNT","misconceptions":{"Comparar somente 45% com 30% e concluir a quantidade absoluta.":["RATE_COMPARED_AS_ABSOLUTE_COUNT"]},"position":12},{"id":"v5-math-percent-base-17","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"IDENTIFY","contextFamily":"REVERSE_PERCENT","statement":"Depois de um desconto de 20%, um produto custa R$ 96. Para verificar o desconto percentual, qual valor é a base?","options":["O preço antes do desconto, ainda desconhecido.","R$ 96, preço depois do desconto.","R$ 20, taxa anunciada.","R$ 76, diferença entre 96 e 20."],"correctAnswer":"O preço antes do desconto, ainda desconhecido.","explanation":"A taxa de desconto é definida em relação ao preço original. Para encontrá-lo, pode-se resolver 0,8 × base = 96; a base não é o preço final.","hint":"O valor conhecido depois da mudança não substitui o valor de referência original.","errorFocus":"KNOWN_FINAL_USED_AS_PERCENT_BASE","misconceptions":{"R$ 96, preço depois do desconto.":["KNOWN_FINAL_USED_AS_PERCENT_BASE"]},"position":13},{"id":"v5-math-percent-base-18","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"TWO_STAGE_DISCOUNT","statement":"Um preço de R$ 200 recebe 10% de desconto e, depois, mais 10% sobre o preço já reduzido. Qual valor serve de base para o segundo desconto?","options":["R$ 200, preço original.","R$ 180, o preço após o primeiro desconto.","10%, a taxa.","R$ 20, o valor do primeiro desconto."],"correctAnswer":"R$ 180, o preço após o primeiro desconto.","explanation":"O primeiro desconto reduz R$ 200 em R$ 20, chegando a R$ 180. O segundo 10% incide sobre o valor atualizado.","hint":"Calcule o valor intermediário antes de identificar a segunda base.","errorFocus":"SAME_RATE_ASSUMED_SAME_BASE","misconceptions":{"R$ 200, preço original.":["SAME_RATE_ASSUMED_SAME_BASE"]},"position":14},{"id":"v5-math-percent-base-19","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"TRANSFER","contextFamily":"CLASS_CHANGE","statement":"Uma turma tinha 24 participantes e, no semestre seguinte, 30. A pergunta é “o crescimento em relação ao semestre anterior”. Qual é a base?","options":["30 participantes, o total mais recente.","6 participantes, o acréscimo.","24 participantes, o total do semestre anterior.","27 participantes, a média dos dois semestres."],"correctAnswer":"24 participantes, o total do semestre anterior.","explanation":"A expressão “em relação ao semestre anterior” define a referência inicial: 24.","hint":"Localize explicitamente o período de referência na pergunta.","errorFocus":"REFERENCE_PERIOD_IGNORED","misconceptions":{"30 participantes, o total mais recente.":["REFERENCE_PERIOD_IGNORED"]},"position":1},{"id":"v5-math-percent-base-20","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"TRANSFER","contextFamily":"TWO_DENOMINATORS","statement":"Em uma escola, 18 de 60 estudantes participam de um clube. Desses 18, 12 frequentam semanalmente. Para calcular a porcentagem semanal entre participantes do clube, qual é a base?","options":["60 estudantes da escola.","12 frequentadores semanais.","42 estudantes que não participam do clube.","18 participantes do clube."],"correctAnswer":"18 participantes do clube.","explanation":"O grupo de comparação é “participantes do clube”; dentro dele, 12 de 18 frequentam semanalmente.","hint":"Identifique a frase que define a população da porcentagem.","errorFocus":"WHOLE_GROUP_SELECTED_TOO_BROADLY","misconceptions":{"60 estudantes da escola.":["WHOLE_GROUP_SELECTED_TOO_BROADLY"]},"position":2},{"id":"v5-math-percent-base-21","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"TRANSFER","contextFamily":"REVENUE_COMPARISON","statement":"A receita de um projeto passou de R$ 5.000 para R$ 5.500. Outra equipe calcula o crescimento usando R$ 5.500 como divisor. Qual correção deve fazer?","options":["Usar R$ 5.000 como base inicial para a variação de crescimento.","Usar R$ 500, a diferença, como base.","Manter R$ 5.500 porque é o valor mais recente.","Usar R$ 10.500, a soma dos períodos."],"correctAnswer":"Usar R$ 5.000 como base inicial para a variação de crescimento.","explanation":"A taxa de crescimento de um período para o seguinte é relativa ao valor de partida, R$ 5.000.","hint":"A base de uma variação é o valor antes da mudança.","errorFocus":"FINAL_VALUE_USED_AS_GROWTH_BASE","misconceptions":{"Usar R$ 500, a diferença, como base.":["FINAL_VALUE_USED_AS_GROWTH_BASE"]},"position":3},{"id":"v5-math-percent-base-22","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"TRANSFER","contextFamily":"SUCCESSIVE_INCREASES","statement":"Um valor de R$ 400 aumenta 10% e, no mês seguinte, aumenta 10% novamente. Qual é a base do segundo aumento?","options":["R$ 400, o valor original.","O valor após o primeiro aumento: R$ 440.","R$ 40, o primeiro aumento.","10%, a taxa aplicada."],"correctAnswer":"O valor após o primeiro aumento: R$ 440.","explanation":"O primeiro aumento é R$ 40, resultando em R$ 440. A segunda variação usa esse novo valor como referência.","hint":"Atualize a quantidade entre as duas etapas.","errorFocus":"SUCCESSIVE_PERCENTAGES_SHARE_BASE","misconceptions":{"R$ 400, o valor original.":["SUCCESSIVE_PERCENTAGES_SHARE_BASE"]},"position":4},{"id":"v5-math-percent-base-23","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"TRANSFER","contextFamily":"SURVEY_RESPONSE_RATE","statement":"Um formulário foi enviado a 250 pessoas; 175 responderam e 35 respostas vieram de uma região específica. Para calcular a proporção dessa região entre as respostas recebidas, qual é a base?","options":["250 pessoas que receberam o formulário.","35 respostas da região.","175 respostas recebidas.","75 pessoas que não responderam."],"correctAnswer":"175 respostas recebidas.","explanation":"A pergunta usa as respostas recebidas como grupo de referência, não todas as pessoas convidadas.","hint":"O denominador depende de “entre quais pessoas?”.","errorFocus":"INVITED_GROUP_USED_FOR_RESPONDENT_SHARE","misconceptions":{"250 pessoas que receberam o formulário.":["INVITED_GROUP_USED_FOR_RESPONDENT_SHARE"]},"position":5},{"id":"v5-math-percent-base-24","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"TRANSFER","contextFamily":"PRICE_MARKUP_AND_DISCOUNT","statement":"Uma loja aumenta um preço de R$ 80 em 25% e depois oferece 20% de desconto sobre o novo preço. Qual é a base do desconto?","options":["R$ 80, o preço inicial.","R$ 20, o valor numérico da taxa.","R$ 5, diferença entre as taxas.","R$ 100, o preço após o aumento."],"correctAnswer":"R$ 100, o preço após o aumento.","explanation":"O aumento de 25% sobre R$ 80 é R$ 20, então o novo preço é R$ 100. O desconto seguinte usa R$ 100 como base.","hint":"A segunda operação parte do resultado da primeira.","errorFocus":"ORIGINAL_PRICE_USED_FOR_LATER_DISCOUNT","misconceptions":{"R$ 80, o preço inicial.":["ORIGINAL_PRICE_USED_FOR_LATER_DISCOUNT"]},"position":6},{"id":"v5-math-percent-base-25","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"TRANSFER","contextFamily":"MIXED_BASE_REPORT","statement":"Um relatório diz que 15% dos 200 inscritos faltaram. Em seguida, informa que 40% dos faltosos justificaram a ausência. Qual é a base do segundo percentual?","options":["O número de pessoas que faltaram, 15% de 200.","Os 200 inscritos.","Os 40% de justificativas.","As pessoas presentes."],"correctAnswer":"O número de pessoas que faltaram, 15% de 200.","explanation":"O segundo percentual é “entre os faltosos”. Primeiro é preciso identificar esse grupo, que corresponde a 30 pessoas; a base é 30.","hint":"Siga a cadeia: total, grupo selecionado, subgrupo.","errorFocus":"FIRST_BASE_REUSED_FOR_NESTED_PERCENTAGE","misconceptions":{"Os 200 inscritos.":["FIRST_BASE_REUSED_FOR_NESTED_PERCENTAGE"]},"position":7},{"id":"v5-math-percent-base-26","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"RATE_VS_POINT_CHANGE","statement":"Um índice subiu de 40% para 50%. Uma pessoa chama isso de “aumento de 10%”. Qual pergunta esclarece a base antes de aceitar a frase?","options":["Se o índice final é maior.","A pessoa quer dizer aumento de 10 pontos percentuais ou aumento relativo calculado sobre os 40% iniciais?","Se 40% e 50% são números inteiros.","Se a diferença entre as taxas é 90%."],"correctAnswer":"A pessoa quer dizer aumento de 10 pontos percentuais ou aumento relativo calculado sobre os 40% iniciais?","explanation":"A diferença absoluta é 10 pontos percentuais; a variação relativa usa 40% como base e tem outro valor. A frase precisa especificar a medida.","hint":"Peça que a unidade da mudança seja explicitada.","errorFocus":"PERCENT_AND_PERCENTAGE_POINT_AMBIGUITY","misconceptions":{"Se o índice final é maior.":["PERCENT_AND_PERCENTAGE_POINT_AMBIGUITY"]},"position":8},{"id":"v5-math-percent-base-27","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"REVISE_CLAIM","contextFamily":"LOCKIN_BASE_AFTER_CHANGE","statement":"Uma conta passou de R$ 160 para R$ 200. Um cálculo de aumento percentual usa R$ 200 como base. O que deve ser corrigido?","options":["Usar R$ 40, a diferença, como referência.","Usar R$ 200 porque todo cálculo usa o valor final.","Usar R$ 160, o valor inicial, como referência do aumento.","Usar a média de R$ 180 sem justificativa."],"correctAnswer":"Usar R$ 160, o valor inicial, como referência do aumento.","explanation":"Para uma variação de 160 para 200, a base é o valor anterior à mudança. R$ 40 é a diferença absoluta.","hint":"Reescreva “de ___ para ___” e marque o início.","errorFocus":"FINAL_AS_BASE","misconceptions":{"Usar R$ 40, a diferença, como referência.":["FINAL_AS_BASE"]},"position":1},{"id":"v5-math-percent-base-28","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"LOCKIN_SUBGROUP","statement":"Em um grupo de 80 pessoas, 20 são voluntárias. Entre as voluntárias, 5 atuam aos sábados. Para obter a taxa de atuação aos sábados entre voluntárias, qual base usar?","options":["80 pessoas do grupo completo.","5 voluntárias de sábado.","60 pessoas não voluntárias.","20 voluntárias."],"correctAnswer":"20 voluntárias.","explanation":"A frase “entre as voluntárias” define o denominador; a taxa é 5 em relação a 20.","hint":"O grupo depois de “entre” é a base.","errorFocus":"WHOLE_GROUP_REPLACES_CONDITIONED_GROUP","misconceptions":{"80 pessoas do grupo completo.":["WHOLE_GROUP_REPLACES_CONDITIONED_GROUP"]},"position":2},{"id":"v5-math-percent-base-29","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"LOCKIN_SEQUENCE","statement":"Um item de R$ 100 sobe 20% e depois cai 20%. Alguém diz que as taxas se anulam porque usam a mesma base. Qual é o erro?","options":["A segunda taxa incide sobre R$ 120, não sobre os R$ 100 iniciais.","A base de qualquer percentual é sempre 100.","O preço após o aumento continua sendo R$ 100.","A queda de 20% deve ser somada ao aumento sem base."],"correctAnswer":"A segunda taxa incide sobre R$ 120, não sobre os R$ 100 iniciais.","explanation":"Após o primeiro aumento, o preço passa a R$ 120. A redução de 20% é calculada sobre esse valor novo.","hint":"Escreva o valor que existe imediatamente antes de cada operação.","errorFocus":"SEQUENTIAL_CHANGES_ASSUMED_SAME_BASE","misconceptions":{"A base de qualquer percentual é sempre 100.":["SEQUENTIAL_CHANGES_ASSUMED_SAME_BASE"]},"position":3},{"id":"v5-math-percent-base-30","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"LOCKIN_POINTS","statement":"Uma taxa passou de 12% para 15%. Qual frase usa corretamente a diferença absoluta entre as taxas?","options":["A taxa aumentou 3%, sem indicar base.","A taxa aumentou 3 pontos percentuais.","A taxa aumentou 27 pontos percentuais.","A taxa passou a ser 3% do valor inicial."],"correctAnswer":"A taxa aumentou 3 pontos percentuais.","explanation":"15% menos 12% é uma diferença de 3 pontos percentuais. Uma variação percentual relativa teria 12% como base.","hint":"Nomeie unidade e base antes de expressar a mudança.","errorFocus":"PERCENTAGE_POINT_DIFFERENCE_MISLABELED","misconceptions":{"A taxa aumentou 3%, sem indicar base.":["PERCENTAGE_POINT_DIFFERENCE_MISLABELED"]},"position":4},{"id":"v5-math-percent-base-31","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"REVISE_CLAIM","contextFamily":"LOCKIN_ABSOLUTE_COUNTS","statement":"A equipe A relata 50% de participação entre 20 inscritos; a equipe B relata 40% entre 100 inscritos. Qual conclusão sobre quantidades é correta?","options":["A equipe A tem mais participantes porque 50% é maior.","As equipes têm a mesma quantidade porque ambas têm percentuais próximos.","A equipe A tem 10 participantes e a B tem 40; o percentual maior não significa maior quantidade absoluta.","Não é possível calcular sem usar 50% como base."],"correctAnswer":"A equipe A tem 10 participantes e a B tem 40; o percentual maior não significa maior quantidade absoluta.","explanation":"Aplicar cada percentual ao seu próprio total dá 10 e 40. Percentual e quantidade absoluta respondem perguntas diferentes.","hint":"Multiplique cada taxa por sua própria base para comparar quantidades.","errorFocus":"RATE_USED_AS_ABSOLUTE_COUNT","misconceptions":{"A equipe A tem mais participantes porque 50% é maior.":["RATE_USED_AS_ABSOLUTE_COUNT"]},"position":5},{"id":"v5-math-percent-base-32","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"IDENTIFY","contextFamily":"REVIEW_PART_WHOLE","statement":"Uma caixa tem 48 peças, das quais 12 são azuis. Para calcular a porcentagem de peças azuis na caixa, qual é a base?","options":["12 peças, a parte azul.","36 peças, as peças não azuis.","A porcentagem, que ainda não foi calculada.","48 peças, o total da caixa."],"correctAnswer":"48 peças, o total da caixa.","explanation":"A parte azul é comparada com o total da caixa: 12 de 48.","hint":"A expressão “na caixa” aponta para o todo relevante.","errorFocus":"PART_USED_AS_WHOLE","misconceptions":{"12 peças, a parte azul.":["PART_USED_AS_WHOLE"]},"position":1},{"id":"v5-math-percent-base-33","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"IDENTIFY","contextFamily":"REVIEW_ORIGINAL_PRICE","statement":"Um preço de R$ 250 recebeu acréscimo de 8%. Qual é a base do acréscimo?","options":["R$ 250, o preço antes do acréscimo.","R$ 8, valor do acréscimo sem cálculo.","8%, a taxa.","O preço depois do acréscimo."],"correctAnswer":"R$ 250, o preço antes do acréscimo.","explanation":"A taxa é aplicada ao preço inicial de R$ 250.","hint":"Marque o valor anterior à mudança.","errorFocus":"CHANGE_RATE_USED_AS_AMOUNT","misconceptions":{"R$ 8, valor do acréscimo sem cálculo.":["CHANGE_RATE_USED_AS_AMOUNT"]},"position":2},{"id":"v5-math-percent-base-34","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"TRANSFER","contextFamily":"REVIEW_NESTED_GROUP","statement":"Em uma pesquisa, 30% de 300 respostas mencionam transporte; dentro desse grupo, 20% mencionam bicicleta. Para calcular o segundo percentual, qual base usar?","options":["300 respostas totais.","90 respostas que mencionam transporte.","20 respostas.","210 respostas que não mencionam transporte."],"correctAnswer":"90 respostas que mencionam transporte.","explanation":"O grupo de transporte tem 30% de 300, ou 90 respostas. O percentual de bicicleta é calculado em relação a essas 90.","hint":"Calcule ou nomeie o grupo intermediário antes do subgrupo.","errorFocus":"TOTAL_USED_FOR_CONDITIONAL_PERCENT","misconceptions":{"300 respostas totais.":["TOTAL_USED_FOR_CONDITIONAL_PERCENT"]},"position":3},{"id":"v5-math-percent-base-35","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"REVIEW_RELATIVE_CHANGE","statement":"Uma quantidade passou de 50 para 65. Qual valor deve aparecer no denominador ao calcular a variação percentual desde o início?","options":["65, a quantidade final.","15, a diferença absoluta.","50, a quantidade inicial.","115, a soma dos valores."],"correctAnswer":"50, a quantidade inicial.","explanation":"A variação percentual desde o início é relativa ao valor inicial. A diferença absoluta é 15.","hint":"“Desde o início” define a base temporal.","errorFocus":"CHANGE_AMOUNT_USED_AS_DENOMINATOR","misconceptions":{"65, a quantidade final.":["CHANGE_AMOUNT_USED_AS_DENOMINATOR"]},"position":4},{"id":"v5-math-percent-base-36","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"REVIEW_SUCCESSIVE","statement":"Um preço de R$ 300 cai 10% e depois sobe 10% sobre o valor reduzido. Qual é a base do aumento final?","options":["R$ 300, o preço original.","R$ 30, o valor da primeira redução.","10%, a taxa do aumento.","R$ 270, o preço após a redução."],"correctAnswer":"R$ 270, o preço após a redução.","explanation":"A redução de 10% leva o preço a R$ 270; o aumento seguinte incide sobre R$ 270.","hint":"Atualize o valor entre operações sucessivas.","errorFocus":"ORIGINAL_VALUE_USED_FOR_SECOND_CHANGE","misconceptions":{"R$ 300, o preço original.":["ORIGINAL_VALUE_USED_FOR_SECOND_CHANGE"]},"position":5},{"id":"v5-math-percent-base-37","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"REVIEW_PERCENT_OF_SUBGROUP","statement":"Em um total de 500 solicitações, 100 são de um bairro; 30 dessas 100 foram concluídas. Para expressar conclusões entre solicitações do bairro, qual é a base?","options":["100 solicitações do bairro.","500 solicitações totais.","30 solicitações concluídas.","400 solicitações de outros bairros."],"correctAnswer":"100 solicitações do bairro.","explanation":"A referência é o conjunto de solicitações daquele bairro. A taxa é 30 em relação a 100, não ao total geral.","hint":"Leia o escopo geográfico definido pela pergunta.","errorFocus":"GLOBAL_BASE_USED_FOR_LOCAL_RATE","misconceptions":{"500 solicitações totais.":["GLOBAL_BASE_USED_FOR_LOCAL_RATE"]},"position":6},{"id":"v5-math-percent-base-38","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"REVIEW_BASE_AMBIGUITY","statement":"Uma notícia afirma “a participação cresceu 5%”, mas não informa a taxa anterior. O que falta para interpretar a variação relativa?","options":["Apenas o número final, pois a taxa de crescimento já define a base.","A base inicial da participação e a definição de como a variação foi calculada.","O número de pessoas que não participaram.","A soma da taxa inicial e final."],"correctAnswer":"A base inicial da participação e a definição de como a variação foi calculada.","explanation":"Sem o valor de referência, não se calcula nem se interpreta completamente uma variação relativa. A diferença em pontos percentuais também pode ser distinta.","hint":"Pergunte “5% de qual valor inicial?” e qual unidade está sendo usada.","errorFocus":"MISSING_BASE_HIDDEN","misconceptions":{"Apenas o número final, pois a taxa de crescimento já define a base.":["MISSING_BASE_HIDDEN"]},"position":7},{"id":"v5-math-percent-base-39","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"REVIEW_BASE_CHAIN","statement":"Uma taxa de 25% incide sobre um grupo de 80; depois, 50% da parte obtida é destinada a outro uso. Qual é a base do segundo percentual?","options":["80, total do primeiro cálculo.","25%, taxa inicial.","A parte obtida no primeiro cálculo: 25% de 80, ou 20.","50%, taxa do segundo cálculo."],"correctAnswer":"A parte obtida no primeiro cálculo: 25% de 80, ou 20.","explanation":"O primeiro percentual gera 20. O segundo enunciado diz “da parte obtida”, portanto 20 se torna a nova base.","hint":"Siga a cadeia e renomeie cada resultado intermediário.","errorFocus":"INTERMEDIATE_RESULT_NOT_UPDATED_AS_BASE","misconceptions":{"80, total do primeiro cálculo.":["INTERMEDIATE_RESULT_NOT_UPDATED_AS_BASE"]},"position":8},{"id":"v5-math-percent-base-40","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"TRANSFER","contextFamily":"REVIEW_COMPARE_BANDS","statement":"Em uma faixa etária há 18% de adesão entre 50 pessoas; em outra, 12% entre 200. Qual afirmação separa corretamente taxa e quantidade?","options":["A primeira faixa tem necessariamente mais pessoas aderentes.","A segunda faixa tem taxa maior porque seu total é maior.","As taxas não podem ser comparadas quando as bases diferem.","A primeira faixa tem taxa maior; a segunda pode ter mais pessoas aderentes porque sua base é maior."],"correctAnswer":"A primeira faixa tem taxa maior; a segunda pode ter mais pessoas aderentes porque sua base é maior.","explanation":"Taxas de grupos diferentes podem ser comparadas como proporções, mas as quantidades dependem de cada base: 9 e 24 pessoas, respectivamente.","hint":"Calcule separadamente a parte e mantenha o percentual como medida relativa.","errorFocus":"RATE_AND_COUNT_CONFLATED","misconceptions":{"A primeira faixa tem necessariamente mais pessoas aderentes.":["RATE_AND_COUNT_CONFLATED"]},"position":9}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 1, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-math-percent-base-reference',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 1
       and metadata->>'content_id' = 'v5-math-percent-base-reference' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'MATHEMATICS', 'PERCENTAGE', 'identificar_base_percentual_em_contexto',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

